public class BuilderVsBuffer {
    public static void main(String[] args) {
        // StringBuilder: NOT synchronized -> faster, single-threaded code
        StringBuilder sb = new StringBuilder();
        sb.append("user").append('-').append(42);
        System.out.println(sb.toString()); // user-42

        // StringBuffer: synchronized -> thread-safe but slower
        StringBuffer buffer = new StringBuffer("log:");
        buffer.append(" started").insert(0, "[");
        System.out.println(buffer); // [log: started

        // Same API; pick StringBuilder unless many threads mutate one instance
    }
}

public class ReportGenerator {
    public String generateUserReport(String userId, List<String> activities) {
        var sb = new StringBuilder(200); // pre-size for efficiency

        sb.append("User Report for ID: ").append(userId).append("\n");
        sb.append("Generated: ").append(LocalDateTime.now()).append("\n\n");

        sb.append("Activities:\n");
        for (var activity : activities) {
            sb.append("  - ").append(activity).append("\n");
        }

        // insert summary at specific position
        int summaryPos = sb.indexOf("Activities:");
        sb.insert(summaryPos, "Total Count: " + activities.size() + "\n");

        // remove trailing newline
        sb.deleteCharAt(sb.length() - 1);

        return sb.toString(); // convert to immutable String
    }
}

public class StringVsBuilder {
    public static void main(String[] args) {
        // BAD: '+' in a loop creates a new String each pass (O(n^2))
        String slow = "";
        for (int i = 0; i < 5; i++) {
            slow += i; // a new String object every iteration
        }
        System.out.println(slow); // 01234

        // GOOD: StringBuilder mutates one buffer (O(n))
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 5; i++) {
            sb.append(i);
        }
        System.out.println(sb); // 01234

        // Fine for a few fixed joins - the compiler optimizes this
        String name = "id-" + 7;
        System.out.println(name); // id-7
    }
}

public class TextProcessor {
    public String sanitizeAndFormat(String rawInput) {
        // String to StringBuilder: constructor copies char data
        var sb = new StringBuilder(rawInput);

        // modify in place: remove whitespace, add prefix
        for (int i = sb.length() - 1; i >= 0; i--) {
            if (Character.isWhitespace(sb.charAt(i))) {
                sb.deleteCharAt(i);
            }
        }
        sb.insert(0, "[SANITIZED] ");

        // StringBuilder to String: toString() copies to immutable String
        return sb.toString();
    }

    // ANTI-PATTERN: toString() in loop
    public List<String> badConversion(List<String> words) {
        var sb = new StringBuilder();
        var results = new ArrayList<String>();
        for (var word : words) {
            sb.append(word).append(" ");
            results.add(sb.toString()); // allocates new String each iteration!
        }
        return results;
    }
}

public class CsvExporter {
    public String exportOrders(List<Order> orders) {
        // estimate: 150 chars per row, plus header
        int estimatedSize = 100 + (orders.size() * 150);
        var sb = new StringBuilder(estimatedSize);

        sb.append("OrderID,Customer,Amount,Status\n");

        for (var order : orders) {
            sb.append(order.id()).append(",")
              .append(order.customer()).append(",")
              .append(order.amount()).append(",")
              .append(order.status()).append("\n");
        }

        // no internal resizing occurred if estimate was accurate
        return sb.toString();
    }
}

record Order(Long id, String customer, double amount, String status) {}
